import{_ as t,o as a,c as o,a2 as l}from"./chunks/framework.A5mep7Fe.js";const p=JSON.parse('{"title":"🤖 08 · 主流模型专题（本质对比）","description":"","frontmatter":{},"headers":[],"relativePath":"01-算法岗-AIGC与LLM/08-主流模型专题.md","filePath":"01-算法岗-AIGC与LLM/08-主流模型专题.md","lastUpdated":1786806808000}'),r={name:"01-算法岗-AIGC与LLM/08-主流模型专题.md"};function d(n,e,i,h,c,s){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="🤖-08-·-主流模型专题-本质对比" tabindex="-1">🤖 08 · 主流模型专题（本质对比） <a class="header-anchor" href="#🤖-08-·-主流模型专题-本质对比" aria-label="Permalink to &quot;🤖 08 · 主流模型专题（本质对比）&quot;">​</a></h1><blockquote><p>框架会过时，<strong>架构思想</strong>才会留存。本篇不背参数，而是对比各家「设计取舍」——这才是面试加分点。</p></blockquote><hr><h2 id="一、gpt-系-decoder-only-自回归鼻祖" tabindex="-1">一、GPT 系（Decoder-only 自回归鼻祖） <a class="header-anchor" href="#一、gpt-系-decoder-only-自回归鼻祖" aria-label="Permalink to &quot;一、GPT 系（Decoder-only 自回归鼻祖）&quot;">​</a></h2><ul><li>纯 Decoder，CLM 预训练，堆叠层 + 掩码注意力。</li><li>GPT-3 证明「规模即能力」；InstructGPT 确立 RLHF 三阶段范式。</li><li>闭源，生态强（API/工具链）。</li></ul><h2 id="二、llama-系-开源标杆" tabindex="-1">二、LLaMA 系（开源标杆） <a class="header-anchor" href="#二、llama-系-开源标杆" aria-label="Permalink to &quot;二、LLaMA 系（开源标杆）&quot;">​</a></h2><ul><li>Meta 开源，Decoder-only，RMSNorm + RoPE + SwiGLU + GQA（2 代起）。</li><li>数据配比与工程细节优秀，成为开源生态底座（无数衍生模型）。</li><li>本质：用相对小的参数 + 高质量数据 + 现代架构，达到接近闭源的效果。</li></ul><h2 id="三、qwen-通义千问-阿里" tabindex="-1">三、Qwen（通义千问，阿里） <a class="header-anchor" href="#三、qwen-通义千问-阿里" aria-label="Permalink to &quot;三、Qwen（通义千问，阿里）&quot;">​</a></h2><ul><li>全尺寸覆盖（0.5B→72B+，含 MoE 版 Qwen-Max/MoE）。</li><li>中文与多语言能力突出，工具调用/Agent 支持好，开源友好。</li><li>配套生态完整（微调、部署、Agent 框架）。</li></ul><h2 id="四、deepseek-深度求索" tabindex="-1">四、DeepSeek（深度求索） <a class="header-anchor" href="#四、deepseek-深度求索" aria-label="Permalink to &quot;四、DeepSeek（深度求索）&quot;">​</a></h2><ul><li><strong>DeepSeek-V 系</strong>：极致性价比，MoE 架构，长上下文。</li><li><strong>DeepSeek-R1</strong>：用 GRPO + 可验证奖励（RLVR）做推理训练，激发长链思维（CoT），开创「推理模型」开源路线。</li><li>本质贡献：证明「强化学习 + 可验证奖励」能显著提升推理能力，且成本极低。</li></ul><h2 id="五、claude-anthropic" tabindex="-1">五、Claude（Anthropic） <a class="header-anchor" href="#五、claude-anthropic" aria-label="Permalink to &quot;五、Claude（Anthropic）&quot;">​</a></h2><ul><li>强调「Constitutional AI」（宪法式对齐），安全与长文本能力强。</li><li>闭源，偏企业/长文档/代码场景。</li></ul><hr><h2 id="六、横向对比-面试常问「怎么选模型」" tabindex="-1">六、横向对比（面试常问「怎么选模型」） <a class="header-anchor" href="#六、横向对比-面试常问「怎么选模型」" aria-label="Permalink to &quot;六、横向对比（面试常问「怎么选模型」）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>开源(LlaMA/Qwen/DeepSeek)</th><th>闭源(GPT/Claude)</th></tr></thead><tbody><tr><td>可控性</td><td>可微调/私有部署</td><td>仅 API</td></tr><tr><td>成本</td><td>自托管可压低</td><td>按 token 计费</td></tr><tr><td>数据隐私</td><td>可完全本地</td><td>数据出域</td></tr><tr><td>能力上限</td><td>追平中大型</td><td>通常领先</td></tr><tr><td>迭代速度</td><td>社区快</td><td>厂商快</td></tr></tbody></table><p><strong>选型本质</strong>：数据敏感/成本敏感/需定制 → 开源自部署；追求最强能力/快速接入 → 闭源 API；生产常「闭源主力 + 开源兜底」混合。</p><hr><h2 id="七、高频追问" tabindex="-1">七、高频追问 <a class="header-anchor" href="#七、高频追问" aria-label="Permalink to &quot;七、高频追问&quot;">​</a></h2><p><strong>Q1：Decoder-only 为什么成为 LLM 主流而非 Enc-Dec？</strong></p><blockquote><p>自回归生成天然契合 Decoder-only；统一预训练目标简单；规模化经验最丰富；Encoder 的双向理解可由指令微调补偿。</p></blockquote><p><strong>Q2：DeepSeek-R1 的「推理能力」来自哪？</strong></p><blockquote><p>主要来自 GRPO 强化学习 + 可验证奖励（数学/代码对错），让模型学会「先想再做」的长链推理，而非仅靠 SFT 模仿。</p></blockquote><p><strong>Q3：怎么给业务选模型？</strong></p><blockquote><p>看：数据隐私、成本预算、延迟要求、是否需要微调、能力下限是否满足。没有万能模型，先定约束再选。</p></blockquote><hr><p>➡️ 返回：<a href="./README">01-算法岗-AIGC与LLM README</a> ｜ 进入：<a href="./../02-算法岗-AIGC生成式/README">02-算法岗-AIGC生成式</a></p>',27)])])}const b=t(r,[["render",d]]);export{p as __pageData,b as default};
